content.text:
        if row[p]:
            abo[p].append(i)
pktb = [[] for _ in range(R + 1)]

sb = [[] for _ in range(R + 1)]
for j, sd in enumerate(trace['sends']):
    sb[int(sd[1])].append((int(sd[0]), j))
for t in range(R + 1):
    if sb[t]:
        sb[t].sort()
sstatus = [None] * len(trace['sends'])

delivered = adopted_cnt = unk_cnt = stale_cnt = pending = 0
peak = 0
always_known = True

qbuck = {}
for qi, tk in enumerate(trace['queries']):
    tk = int(tk)
    qbuck.setdefault(tk, []).append(qi)
states = [None] * len(trace['queries'])

for t in range(R + 1):
    ph = t % P
    # 1. local drift over interval [t-1, t)
    if t > 0:
        row = rates[t - 1]
        vrow = self.VHp[(t - 1) % P]
        for i in range(N):
            if bnd[i] is not None:
                e = err[i] + row[i] * T
                err[i] = e
                bnd[i] = bnd[i] + vrow[i]
                ae = -e if e < 0 else e
                if ae > peak:
                    peak = ae
    # 2. reboots (before anchors)
    for nd in rbo[t]:
        if bnd[nd] is not None:
            n_known -= 1
        gen[nd] += 1
        err[nd] = None
        bnd[nd] = None
    # 3. anchor service
    for nd in abo[ph]:
        if bnd[nd] is None:
            n_known += 1
        err[nd] = 0
        bnd[nd] = 0
    # 4. due applications grouped per receiver
    due = pktb[t]
    adoptmark = {}
    if due:
        byrec = {}
        for pk in due:
            dstn = pk[0]
            lst = byrec.get(dstn)
            if lst is None:
                byrec[dstn] = [pk]
            else:
                lst.append(pk)
        delivered += len(due)
        for dstn, pks in byrec.items():
            bestpk = None
            for pk in pks:  # (dst, id, src, err, bound, gens, gend)
                if pk[5] != gen[pk[2]] or pk[6] != gen[dstn]:
                    stale_cnt += 1
                    continue
                if pk[3] is None:
                    unk_cnt += 1
                    continue
                if bestpk is None or (pk[4], pk[1]) < (bestpk[4], bestpk[1]):
                    bestpk = pk
            if bestpk is not None:
                held = bnd[dstn]
                if held is None or bestpk[4] < held:
                    if held is None:
                        n_known += 1
                    e = bestpk[3]
                    err[dstn] = e
                    bnd[dstn] = bestpk[4]
                    adopted_cnt += 1
                    ae = -e if e < 0 else e
                    if ae > peak:
                        peak = ae
                    adoptmark[dstn] = bestpk[1]
    if n_known != N:
        always_known = False
    # 5. query snapshots (post-service, pre-send)
    if t in qbuck:
        bd = bnd[:]
        ed = err[:]
        ad = [None] * N
        for nd, pid in adoptmark.items():
            ad[nd] = pid
        gd = gen[:]
        for qi in qbuck[t]:
            states[qi] = {"bounds_as": bd, "errors_as": ed,
                          "adopted": ad, "generations": gd}
    # 6. sends at this boundary, in packet-id order
    if sb[t]:
        reserved = set()
        rho = self.phase_rho[ph]
        slset = self.slice_set[self.phase_slice[ph]]
        for sid, j in sb[t]:
            sd = trace['sends'][j]
            code = int(sd[2])
            jit = int(sd[3])
            l = code >> 1
            if l not in slset:
                sstatus[j] = 'not_in_slice'
                continue
            n0, n1, gu, gw, d, mm, LL, qq, fd, part_ns = dirs[code]
            bp = self.BP.get(l)
            if bp is not None and bp[ph + mm] > bp[ph]:
                sstatus[j] = 'blackout'
                continue
            if rho < g or rho + d + g > S:
                sstatus[j] = 'guard'
                continue
            key = (n0, int(links[l]['ends'][code & 1][1]))
            if key in reserved:
                sstatus[j] = 'port_busy'
                continue
            reserved.add(key)
            if sid in lost:
                sstatus[j] = 'lost'
                continue
            sstatus[j] = 'sent'
            e0 = err[n0]
            pa = t + LL
            if e0 is None:
                cerr = None
                cbnd = None
            else:
                cerr = e0 + (bias[gw] - bias[gu]) * PS + jit - Cm[gu][gw]
                cbnd = bnd[n0] + Hm[gu][gw]
                # effective aging over [tr, pa), phase periodic
                if part_ns:
                    cbnd += part_ns * self.EFFP[n1][(t + fd) % P]
                for r in range(t + mm, pa):
                    cbnd += VH[n1][r % P]
            if pa > R:
                pending += 1
                continue
            if cerr is not None:
                if part_ns:
                    cerr += rates[t + fd][n1] * part_ns
                for r in range(t + mm, pa):
                    cerr += rates[r][n1] * T
            pktb[pa].append((n1, sid, n0, cerr, cbnd, gen[n0], gen[n1]))

return {"status": "ok", "states": states,
        "send_status": sstatus,
        "delivered": delivered, "adopted": adopted_cnt,
        "unknown_payloads": unk_cnt, "stale_payloads": stale_cnt,
